export const CURL_MIN_PAGE_WIDTH = 220 // phone-readable floor
export const CURL_MAX_PAGE_WIDTH = 1400
export const CURL_PAGE_RATIO = 530 / 370
export const CURL_RASTER_WIDTH = 960
export const CURL_RASTER_HEIGHT = Math.round(
  CURL_RASTER_WIDTH * CURL_PAGE_RATIO,
)
export const CURL_SIZE_QUANTUM = 16
export const CURL_CLICK_SLOP_PX = 24
/** Touch jitter is looser than a mouse click — but the first pixels of a
    flick should already be turning the page, not sitting in a dead zone. */
export const CURL_TOUCH_SLOP_PX = 10
export const CURL_STAGE_PAD_X = 24
/** A spread is only worth showing if each leaf stays comfortably readable. */
export const CURL_SPREAD_MIN_PAGE_WIDTH = 260
/** …and if showing two pages barely shrinks them: a landscape laptop or
    iPad, not a portrait phone where each leaf would be half as tall. */
export const CURL_SPREAD_MIN_HEIGHT_SHARE = 0.85

export type CurlPageSize = {
  width: number
  height: number
}

export type CurlClickIntent = 'prev' | 'next'

export function curlPageSizeForStage(
  clientWidth: number,
  clientHeight: number,
  ratio: number = CURL_PAGE_RATIO,
  spread = false,
) {
  const padX = CURL_STAGE_PAD_X
  const padY = 36
  // A spread holds two leaves side by side, so each gets half the stage.
  const usable = spread ? (clientWidth - padX) / 2 : clientWidth - padX
  const availW = Math.max(1, Math.floor(usable))
  if (clientHeight < 80) {
    const width = Math.min(availW, 360)
    return { width, height: Math.round(width * ratio) }
  }
  const availH = Math.max(1, Math.floor(clientHeight - padY))
  const width = Math.min(
    CURL_MAX_PAGE_WIDTH,
    availW,
    Math.floor(availH / ratio),
  )
  // Floor at the readable minimum only when it still fits both axes — a
  // clipped page reads as broken, a small one just reads small.
  const minFits =
    CURL_MIN_PAGE_WIDTH <= availW &&
    Math.round(CURL_MIN_PAGE_WIDTH * ratio) <= availH
  const finalWidth =
    width < CURL_MIN_PAGE_WIDTH && minFits ? CURL_MIN_PAGE_WIDTH : width
  return { width: finalWidth, height: Math.round(finalWidth * ratio) }
}

export function quantizeCurlPageSize(
  size: CurlPageSize,
  ratio: number = CURL_PAGE_RATIO,
): CurlPageSize {
  // Floor, never round up: a width snapped past the measured stage would
  // overflow the viewport and clip the page edge.
  const width = Math.max(
    1,
    Math.floor(size.width / CURL_SIZE_QUANTUM) * CURL_SIZE_QUANTUM,
  )
  return { width, height: Math.round(width * ratio) }
}

export function curlClickIntent(
  x: number,
  width: number,
  canGoPrev: boolean,
  canGoNext: boolean,
): CurlClickIntent | null {
  if (!canGoPrev && !canGoNext) return null
  // Halves, not thirds: in fullscreen the reader chrome claims the middle
  // band first (tapConsumedByChrome), and outside it there is no chrome to
  // give the middle to, so the whole page stays a turn target.
  const preferPrev = width > 0 && x < width / 2
  // On the cover a tap anywhere opens the book. At the end, a tap on the
  // "next" side does nothing — silently turning backward reads as a bug.
  if (preferPrev) return canGoPrev ? 'prev' : 'next'
  return canGoNext ? 'next' : null
}

/** A released fold turns the page once it has travelled this far (0–100,
    where 50 is the corner reaching the spine). Waiting for the spine means
    reaching the far left edge on a phone, so honest drags snapped back. */
export const CURL_COMMIT_PROGRESS = 25

/** px/ms toward the turn that counts as a flick regardless of distance.
    Between Sonner's 0.11 swipe-dismiss and a deliberate slow drag (~0.1),
    so a quick thumb flick always turns and an unhurried release reads by
    distance. */
export const CURL_COMMIT_VELOCITY = 0.2

/**
 * Whether a released fold completes the turn. `towardVelocity` is the
 * release velocity in the direction that finishes the turn (px/ms, negative
 * when the finger was pulling back). A clear flick back always cancels, a
 * flick forward always commits, otherwise distance decides.
 */
export function curlShouldCommit(
  progress: number,
  towardVelocity: number,
): boolean {
  if (towardVelocity <= -CURL_COMMIT_VELOCITY) return false
  if (towardVelocity >= CURL_COMMIT_VELOCITY) return true
  return progress >= CURL_COMMIT_PROGRESS
}

/** Release velocity (px/ms) from recent samples — the last ~80ms only, so a
    drag that paused before lifting reads as still, not as a flick. */
export function curlReleaseVelocity(
  samples: readonly { x: number; t: number }[],
  windowMs = 80,
): number {
  if (samples.length < 2) return 0
  const last = samples[samples.length - 1]
  let first = last
  for (let index = samples.length - 2; index >= 0; index -= 1) {
    if (last.t - samples[index].t > windowMs) break
    first = samples[index]
  }
  const dt = last.t - first.t
  return dt > 0 ? (last.x - first.x) / dt : 0
}

/**
 * Whether the stage should show two facing pages. Only when both leaves stay
 * readable and the pair is nearly as tall as a single page would be — the
 * shape of the stage decides, so rotating a tablet flips between the two.
 */
export function curlUseSpread(
  clientWidth: number,
  clientHeight: number,
  ratio: number = CURL_PAGE_RATIO,
): boolean {
  const single = curlPageSizeForStage(clientWidth, clientHeight, ratio, false)
  const paired = curlPageSizeForStage(clientWidth, clientHeight, ratio, true)
  return (
    paired.width >= CURL_SPREAD_MIN_PAGE_WIDTH &&
    paired.height >= single.height * CURL_SPREAD_MIN_HEIGHT_SHARE
  )
}

/** First page of the spread holding `pageIndex` — spreads pair (1|2),
    (3|4)… from the first page, like a document's two-page view. */
export function curlSpreadStart(pageIndex: number): number {
  return Math.max(0, pageIndex - (pageIndex % 2))
}

/** Where a next/previous turn lands: one page, or one whole spread. Null
    when there is nothing that way. */
export function curlStepTarget(
  from: number,
  direction: 1 | -1,
  pageCount: number,
  spread: boolean,
): number | null {
  if (!spread) {
    const next = from + direction
    return next >= 0 && next < pageCount ? next : null
  }
  const next = curlSpreadStart(from) + direction * 2
  return next >= 0 && next < pageCount ? next : null
}

'use client'

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type ReactNode,
} from 'react'
import { IconChevronLeft, IconChevronRight } from '@tabler/icons-react'
import { Button } from '@/components/ui/button'
import { playPageTurnSound } from '../audio'
import { useBookPreview } from '../book-preview-provider'
import { useStableHandler } from '../hooks/use-stable-handler'
import { tapConsumedByChrome } from '../hooks/use-immersive-chrome'
import {
  CURL_CLICK_SLOP_PX,
  CURL_PAGE_RATIO,
  CURL_TOUCH_SLOP_PX,
  curlClickIntent,
  curlPageSizeForStage,
  curlReleaseVelocity,
  curlShouldCommit,
  curlSpreadStart,
  curlStepTarget,
  curlUseSpread,
  quantizeCurlPageSize,
  type CurlPageSize,
} from './curl-geometry'
import {
  CURL_PEEK_PROGRESS,
  constrainCurlDrag,
  curlBackwardProgress,
  curlDragPoint,
  curlFold,
  curlForwardProgress,
  curlPolygonCss,
  curlSettleMs,
  curlSpreadBackwardProgress,
  easeInOutCubic,
  easeOutCubic,
} from './curl-math'

/** Which side of the spine a leaf is rendered for — decides its gutter. */
export type CurlLeafSide = 'left' | 'right'

type CurlStageProps = {
  pageIndex: number
  pageCount: number
  /** Renders one leaf. Only the few leaves around the reading position are
      mounted, so a 700-page document costs the same as a 7-page one. */
  renderPage: (index: number, side: CurlLeafSide) => ReactNode
  /** height / width of a sheet. Defaults to the paper-book ratio; PDF sources
      pass their own so the book matches the document instead of letterboxing. */
  pageRatio?: number
  /** Colour of the paper on the back of a turning leaf. Rasterized PDF
      pages are white whatever the theme; typeset pages use the reader's. */
  leafBack?: string
  reducedMotion: boolean
  soundEnabled: boolean
  onPageChange: (pageIndex: number) => void
}

type Direction = 'next' | 'prev'

/** A leaf in the air. `p` is 0 flat on the right, 1 turned over the spine. */
type Turn = {
  direction: Direction
  /** The turning leaf: its front shows on the right of the spine. */
  leaf: number
  /** What the leaf's back shows — the next left page in a spread, the leaf
      itself (seen through the paper) on a single page. */
  back: number
  /** The page the leaf uncovers on the right, if there is one. */
  under: number | null
  /** The left page that stays put under the landing leaf (spreads only). */
  still: number | null
  top: boolean
  p: number
  dy: number
  /** Where the reading position lands once this turn completes; null
      while the reader's hand still decides. */
  landing: number | null
  peek: boolean
}

type Layout = { size: CurlPageSize; spread: boolean }

/** A turn from a tap, the arrows, or the keyboard. Longer than UI motion
    (this is the hero of the component), still short enough that a fast
    reader tapping through never waits: a new turn lands the old one. */
const CURL_TURN_MS = 540
const CURL_PEEK_MS = 220
/** Mouse this close to a corner lifts it. */
const CURL_CORNER_PX = 64

function isInteractiveTarget(target: EventTarget | null) {
  if (!(target instanceof Element)) return false
  return Boolean(
    target.closest(
      'a, button, input, textarea, select, [data-book-preview-press]',
    ),
  )
}

/** Fore-edge page-stack thickness: a few pixels, growing gently with the
    number of leaves on that side — enough to read as a book block. */
function curlEdgeWidth(pageCountOnSide: number): number {
  if (pageCountOnSide <= 0) return 0
  return Math.min(6, 2 + Math.floor(pageCountOnSide / 8))
}

/** The pages to keep mounted: the spread in view, the one on either side
    (the leaves a turn reveals), and the target of a turn in flight. */
function curlMountWindow(
  shown: number,
  pageIndex: number,
  pageCount: number,
  spread: boolean,
): number[] {
  const set = new Set<number>()
  const span = spread ? [-2, -1, 0, 1, 2, 3, 4, 5] : [-1, 0, 1, 2]
  for (const center of [
    shown,
    spread ? curlSpreadStart(pageIndex) : pageIndex,
  ]) {
    for (const offset of span) {
      const page = center + offset
      if (page >= 0 && page < pageCount) set.add(page)
    }
  }
  return Array.from(set).sort((a, b) => a - b)
}

function show(el: HTMLElement | undefined, z: number, clip: string) {
  if (!el) return
  el.style.visibility = 'visible'
  el.style.zIndex = String(z)
  el.style.clipPath = clip
}

function hide(el: HTMLElement | undefined) {
  if (!el) return
  el.style.visibility = 'hidden'
  el.style.clipPath = ''
}

/**
 * Page-curl book, one page or a two-page spread. The turning leaf is
 * folded, not faked: its flat part is clipped at the fold, its lifted part is
 * mirrored across the fold onto its own back, and whatever it uncovers is
 * already there. A spread's leaf carries the next left page on its back, so
 * it lands reading correctly. The drag follows the finger, a release
 * finishes from wherever the page is, in the direction it was moving, and
 * any new input lands a turn still in the air — nothing waits on animation.
 */
export function CurlStage({
  pageIndex,
  pageCount,
  renderPage,
  pageRatio = CURL_PAGE_RATIO,
  leafBack = 'var(--background)',
  reducedMotion,
  soundEnabled,
  onPageChange,
}: CurlStageProps) {
  const { setPageStep } = useBookPreview()
  const [layout, setLayout] = useState<Layout | null>(null)
  const spread = layout?.spread ?? false
  const [shown, setShown] = useState(() =>
    Math.min(Math.max(pageIndex, 0), Math.max(pageCount - 1, 0)),
  )
  const stageRef = useRef<HTMLDivElement | null>(null)
  const bookRef = useRef<HTMLDivElement | null>(null)
  const shadowRef = useRef<HTMLDivElement | null>(null)
  const frontsRef = useRef(new Map<number, HTMLElement>())
  const backsRef = useRef(new Map<number, HTMLElement>())
  const shownRef = useRef(shown)
  const turnRef = useRef<Turn | null>(null)
  const rafRef = useRef(0)
  const animDoneRef = useRef<(() => void) | null>(null)
  const layoutRef = useRef<Layout | null>(null)
  const settingsRef = useRef({ pageCount, reducedMotion, soundEnabled })
  const report = useStableHandler(onPageChange)

  useLayoutEffect(() => {
    layoutRef.current = layout
    settingsRef.current = { pageCount, reducedMotion, soundEnabled }
  })

  // ---- measuring -------------------------------------------------------

  useEffect(() => {
    const node = stageRef.current
    if (!node || typeof ResizeObserver === 'undefined') return
    let frame = 0
    const measure = () => {
      const wantsSpread =
        pageCount > 1 &&
        curlUseSpread(node.clientWidth, node.clientHeight, pageRatio)
      const size = quantizeCurlPageSize(
        curlPageSizeForStage(
          node.clientWidth,
          node.clientHeight,
          pageRatio,
          wantsSpread,
        ),
        pageRatio,
      )
      setLayout((current) =>
        current &&
        current.spread === wantsSpread &&
        current.size.width === size.width &&
        current.size.height === size.height
          ? current
          : { size, spread: wantsSpread },
      )
    }
    const update = () => {
      if (frame) return
      frame = requestAnimationFrame(() => {
        frame = 0
        measure()
      })
    }
    measure()
    const observer = new ResizeObserver(update)
    observer.observe(node)
    return () => {
      observer.disconnect()
      if (frame) cancelAnimationFrame(frame)
    }
  }, [pageCount, pageRatio])

  // ---- painting ----------------------------------------------------------

  /** Writes the current state straight to the DOM — once per frame while a
      leaf moves, and after every render so newly mounted leaves are placed. */
  const paint = useCallback(() => {
    const fronts = frontsRef.current
    const backs = backsRef.current
    const shadow = shadowRef.current
    const current = layoutRef.current
    const turn = turnRef.current
    const size = current?.size
    const corner =
      size && turn ? { x: size.width, y: turn.top ? 0 : size.height } : null
    const fold =
      turn && size && corner
        ? curlFold(
            corner,
            constrainCurlDrag(
              corner,
              curlDragPoint(corner, turn.p, turn.dy, size.height),
              size.height,
            ),
            size.width,
            size.height,
          )
        : null

    if (!turn || !size || !fold) {
      // At rest. A turn with no fold is a leaf lying flat: the leaf itself
      // (forward, not yet lifted) or what it covers once fully over.
      const base = current?.spread
        ? curlSpreadStart(shownRef.current)
        : shownRef.current
      const visible = new Set<number>()
      if (!turn) {
        visible.add(base)
        if (current?.spread) visible.add(base + 1)
      } else if (turn.p >= 1) {
        if (turn.under !== null) visible.add(turn.under)
        if (current?.spread) visible.add(turn.back)
      } else {
        visible.add(turn.leaf)
        if (turn.still !== null) visible.add(turn.still)
      }
      for (const [index, el] of fronts) {
        if (visible.has(index)) show(el, 2, '')
        else hide(el)
      }
      for (const [index, el] of backs) {
        // A fully turned spread leaf *is* the left page — its back shows.
        if (turn && turn.p >= 1 && current?.spread && index === turn.back) {
          show(el, 4, '')
          el.style.transform = `matrix(-1, 0, 0, 1, 0, 0)`
        } else hide(el)
      }
      if (shadow) shadow.style.opacity = '0'
      return
    }

    for (const [index, el] of fronts) {
      if (index === turn.under || index === turn.still) show(el, 1, '')
      else if (index === turn.leaf) show(el, 2, curlPolygonCss(fold.front))
      else hide(el)
    }
    const [a, b, c, d, e, f] = fold.matrix
    for (const [index, el] of backs) {
      if (index !== turn.back) {
        hide(el)
        continue
      }
      show(el, 4, curlPolygonCss(fold.flap))
      el.style.transform = `matrix(${a}, ${b}, ${c}, ${d}, ${e}, ${f})`
      const gloss = el.lastElementChild
      if (gloss instanceof HTMLElement) {
        placeAlongFold(gloss, fold.origin, fold.angle, fold.depth, size)
      }
    }
    if (shadow) {
      // Shadow on the page underneath, strongest mid-turn, cast from the
      // fold across the uncovered paper.
      const lift = Math.sin(Math.PI * Math.min(Math.max(turn.p, 0), 1))
      const reach = Math.max(24, Math.min(fold.depth * 0.5, size.width * 0.35))
      placeAlongFold(shadow, fold.origin, fold.angle, reach, size)
      shadow.style.opacity = String(Math.min(1, 0.25 + lift))
    }
  }, [])

  useLayoutEffect(() => {
    paint()
  })

  // ---- motion ------------------------------------------------------------

  const stopAnimation = useCallback(() => {
    if (rafRef.current) cancelAnimationFrame(rafRef.current)
    rafRef.current = 0
    animDoneRef.current = null
  }, [])

  const animate = useCallback(
    (
      to: { p: number; dy: number },
      ms: number,
      ease: (t: number) => number,
      done: () => void,
    ) => {
      stopAnimation()
      const turn = turnRef.current
      if (!turn) return
      const from = { p: turn.p, dy: turn.dy }
      const start = performance.now()
      animDoneRef.current = done
      const frame = (now: number) => {
        const current = turnRef.current
        if (!current) return
        const t = ms <= 0 ? 1 : Math.min(1, (now - start) / ms)
        const k = ease(t)
        current.p = from.p + (to.p - from.p) * k
        current.dy = from.dy + (to.dy - from.dy) * k
        paint()
        if (t < 1) {
          rafRef.current = requestAnimationFrame(frame)
          return
        }
        rafRef.current = 0
        const finish = animDoneRef.current
        animDoneRef.current = null
        finish?.()
      }
      rafRef.current = requestAnimationFrame(frame)
    },
    [paint, stopAnimation],
  )

  /** Settles the turn in the air: lands it where it was going, or lays the
      leaf back down. */
  const endTurn = useCallback(() => {
    stopAnimation()
    const turn = turnRef.current
    turnRef.current = null
    if (turn?.landing != null && turn.landing !== shownRef.current) {
      shownRef.current = turn.landing
      setShown(turn.landing)
    }
    paint()
  }, [paint, stopAnimation])

  /** Anything new — a press, a tap, a key — lands a committed turn first,
      so a quick reader turns as fast as they like. */
  const landInFlight = useCallback(() => {
    const turn = turnRef.current
    if (turn && turn.landing != null) endTurn()
  }, [endTurn])

  /** Where a turn in `direction` would land from the current position. */
  const targetOf = useCallback((direction: Direction): number | null => {
    return curlStepTarget(
      shownRef.current,
      direction === 'next' ? 1 : -1,
      settingsRef.current.pageCount,
      Boolean(layoutRef.current?.spread),
    )
  }, [])

  const beginTurn = useCallback(
    (direction: Direction, top: boolean, peek = false): Turn | null => {
      if (targetOf(direction) === null) return null
      const existing = turnRef.current
      if (
        existing &&
        existing.direction === direction &&
        existing.landing == null
      ) {
        existing.top = top
        existing.peek = peek
        return existing
      }
      if (existing) endTurn()
      const count = settingsRef.current.pageCount
      const exists = (page: number) => (page >= 0 && page < count ? page : null)
      let turn: Turn
      if (layoutRef.current?.spread) {
        // Spreads pair (s|s+1). Forward, the right leaf s+1 turns over and
        // its back is the next left page s+2; backward is the same turn of
        // the previous spread, played in reverse.
        const s = curlSpreadStart(shownRef.current)
        turn =
          direction === 'next'
            ? {
                direction,
                leaf: s + 1,
                back: s + 2,
                under: exists(s + 3),
                still: s,
                top,
                p: 0,
                dy: 0,
                landing: null,
                peek,
              }
            : {
                direction,
                leaf: s - 1,
                back: s,
                under: exists(s + 1),
                still: exists(s - 2),
                top,
                p: 1,
                dy: 0,
                landing: null,
                peek,
              }
      } else {
        const current = shownRef.current
        const leaf = direction === 'next' ? current : current - 1
        turn = {
          direction,
          leaf,
          back: leaf,
          under: direction === 'next' ? current + 1 : current,
          still: null,
          top,
          p: direction === 'next' ? 0 : 1,
          dy: 0,
          landing: null,
          peek,
        }
      }
      turnRef.current = turn
      return turn
    },
    [endTurn, targetOf],
  )

  const commit = useCallback(
    (turn: Turn, sound: boolean, announce: boolean) => {
      turn.landing = targetOf(turn.direction)
      if (turn.landing === null) return
      if (sound && settingsRef.current.soundEnabled) playPageTurnSound()
      if (announce) report(turn.landing)
    },
    [report, targetOf],
  )

  /** A whole turn from rest (or from a peek): tap, arrow button, keyboard. */
  const turnPage = useCallback(
    (
      direction: Direction,
      options: { top?: boolean; sound: boolean; announce: boolean },
    ) => {
      landInFlight()
      const target = targetOf(direction)
      if (target === null) return
      if (settingsRef.current.reducedMotion || !layoutRef.current) {
        endTurn()
        if (options.sound && settingsRef.current.soundEnabled) {
          playPageTurnSound()
        }
        shownRef.current = target
        setShown(target)
        if (options.announce) report(target)
        paint()
        return
      }
      const turn = beginTurn(direction, options.top ?? false)
      if (!turn) return
      commit(turn, options.sound, options.announce)
      const remaining = direction === 'next' ? 1 - turn.p : turn.p
      animate(
        { p: direction === 'next' ? 1 : 0, dy: 0 },
        Math.max(160, CURL_TURN_MS * remaining),
        remaining > 0.9 ? easeInOutCubic : easeOutCubic,
        endTurn,
      )
    },
    [
      animate,
      beginTurn,
      commit,
      endTurn,
      landInFlight,
      paint,
      report,
      targetOf,
    ],
  )

  // ---- the reader's page index -----------------------------------------

  // The shell steps by what this book shows: a page, or a whole spread.
  useEffect(() => {
    setPageStep((from, direction) =>
      curlStepTarget(from, direction, pageCount, spread),
    )
    return () => setPageStep(null)
  }, [pageCount, setPageStep, spread])

  useEffect(() => {
    const isSpread = Boolean(layoutRef.current?.spread)
    const wanted = isSpread ? curlSpreadStart(pageIndex) : pageIndex
    const turn = turnRef.current
    if (turn?.landing === wanted) return
    const current = shownRef.current
    const currentBase = isSpread ? curlSpreadStart(current) : current
    // The facing page of the open spread is already on screen.
    if (!turn && wanted === currentBase) return
    landInFlight()
    if (turnRef.current) endTurn()
    const base = isSpread ? curlSpreadStart(shownRef.current) : shownRef.current
    if (wanted === base) return
    // A step from the keyboard or the pager turns the leaf, silently — only
    // the reader's own hand makes the paper sound. Jumps just open there.
    const stride = isSpread ? 2 : 1
    if (Math.abs(wanted - base) === stride) {
      turnPage(wanted > base ? 'next' : 'prev', {
        sound: false,
        announce: false,
      })
      return
    }
    shownRef.current = wanted
    setShown(wanted)
  }, [endTurn, landInFlight, pageIndex, spread, turnPage])

  // A layout switch (rotating a tablet between one page and a spread) or a
  // source swap lands any turn and re-anchors on the reading position.
  useEffect(() => {
    endTurn()
    const clamped = Math.min(Math.max(pageIndex, 0), Math.max(pageCount - 1, 0))
    const next = spread ? curlSpreadStart(clamped) : clamped
    if (next !== shownRef.current) {
      shownRef.current = next
      setShown(next)
    }
    // pageIndex is read, not tracked: the effect above follows it.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [endTurn, pageCount, spread])

  // ---- pointers ----------------------------------------------------------

  useEffect(() => {
    const book = bookRef.current
    if (!book) return
    const press = {
      id: -1,
      startX: 0,
      startY: 0,
      slop: CURL_CLICK_SLOP_PX,
      touch: false,
      dragging: false,
      direction: null as Direction | null,
      last: { x: 0, y: 0 },
      samples: [] as { x: number; t: number }[],
    }

    /** Book coordinates — robust to CSS zoom and transforms on ancestors.
        A spread's book is two pages wide, spine in the middle. */
    const local = (clientX: number, clientY: number) => {
      const rect = book.getBoundingClientRect()
      const current = layoutRef.current
      const bookWidth = current
        ? current.size.width * (current.spread ? 2 : 1)
        : rect.width
      const bookHeight = current ? current.size.height : rect.height
      const sx = rect.width ? bookWidth / rect.width : 1
      const sy = rect.height ? bookHeight / rect.height : 1
      return { x: (clientX - rect.left) * sx, y: (clientY - rect.top) * sy }
    }

    const setCursor = (value: '' | 'grab' | 'grabbing') => {
      if (value) book.dataset.curlCursor = value
      else delete book.dataset.curlCursor
    }

    const onPointerDown = (event: PointerEvent) => {
      if (event.button !== 0 || press.id !== -1) return
      if (isInteractiveTarget(event.target)) return
      landInFlight()
      const pos = local(event.clientX, event.clientY)
      press.id = event.pointerId
      press.startX = pos.x
      press.startY = pos.y
      press.last = pos
      press.samples = [{ x: pos.x, t: event.timeStamp }]
      press.touch = event.pointerType !== 'mouse'
      press.slop = press.touch ? CURL_TOUCH_SLOP_PX : CURL_CLICK_SLOP_PX
      press.dragging = false
      press.direction = null
      try {
        book.setPointerCapture(event.pointerId)
      } catch {
        // Capture is best-effort; the window listeners finish the gesture.
      }
    }

    const peekAt = (pos: { x: number; y: number }) => {
      const current = layoutRef.current
      if (!current || settingsRef.current.reducedMotion) return
      const bookWidth = current.size.width * (current.spread ? 2 : 1)
      const nearEdgeY =
        pos.y < CURL_CORNER_PX || pos.y > current.size.height - CURL_CORNER_PX
      const direction: Direction | null =
        nearEdgeY &&
        pos.x > bookWidth - CURL_CORNER_PX &&
        targetOf('next') !== null
          ? 'next'
          : nearEdgeY &&
              pos.x >= 0 &&
              pos.x < CURL_CORNER_PX &&
              targetOf('prev') !== null
            ? 'prev'
            : null
      const turn = turnRef.current
      if (turn && (turn.landing != null || !turn.peek)) return
      setCursor(direction ? 'grab' : '')
      if (!direction) {
        if (turn?.peek) {
          animate(
            { p: turn.direction === 'next' ? 0 : 1, dy: 0 },
            CURL_PEEK_MS,
            easeOutCubic,
            endTurn,
          )
          turn.peek = false
        }
        return
      }
      if (turn?.peek && turn.direction === direction) return
      const peek = beginTurn(direction, pos.y < current.size.height / 2, true)
      if (!peek) return
      animate(
        {
          p: direction === 'next' ? CURL_PEEK_PROGRESS : 1 - CURL_PEEK_PROGRESS,
          dy: 0,
        },
        CURL_PEEK_MS,
        easeOutCubic,
        () => {},
      )
    }

    const onHover = (event: PointerEvent) => {
      if (press.id !== -1 || event.pointerType !== 'mouse') return
      peekAt(local(event.clientX, event.clientY))
    }

    const onLeave = (event: PointerEvent) => {
      if (press.id !== -1 || event.pointerType !== 'mouse') return
      peekAt({ x: -1e4, y: -1e4 })
    }

    const onPointerMove = (event: PointerEvent) => {
      if (press.id !== event.pointerId) return
      const current = layoutRef.current
      if (!current) return
      const pos = local(event.clientX, event.clientY)
      press.last = pos
      press.samples.push({ x: pos.x, t: event.timeStamp })
      if (press.samples.length > 12) press.samples.shift()
      const dx = pos.x - press.startX
      if (!press.dragging) {
        // Touch turns need horizontal intent — a mostly vertical gesture is
        // the page scrolling. A mouse has no competing gesture.
        const distance = press.touch
          ? Math.abs(dx)
          : Math.hypot(dx, pos.y - press.startY)
        if (distance < press.slop) return
        const direction: Direction = dx < 0 ? 'next' : 'prev'
        press.dragging = true
        press.direction = direction
        setCursor('grabbing')
        if (settingsRef.current.reducedMotion) return
        if (!beginTurn(direction, press.startY < current.size.height / 2)) {
          press.direction = null
          return
        }
        stopAnimation()
      }
      event.preventDefault()
      const turn = turnRef.current
      if (!turn || !press.direction || settingsRef.current.reducedMotion) return
      const width = current.size.width
      turn.p =
        press.direction === 'next'
          ? curlForwardProgress(press.startX, pos.x, width)
          : current.spread
            ? curlSpreadBackwardProgress(press.startX, pos.x, width)
            : curlBackwardProgress(press.startX, pos.x, width)
      turn.dy = pos.y - press.startY
      paint()
    }

    const finish = (event: PointerEvent) => {
      if (press.id !== event.pointerId) return
      const cancelled = event.type === 'pointercancel'
      const pos = cancelled ? press.last : local(event.clientX, event.clientY)
      if (!cancelled) press.samples.push({ x: pos.x, t: event.timeStamp })
      const velocity = cancelled ? 0 : curlReleaseVelocity(press.samples)
      const { dragging, direction } = press
      press.id = -1
      press.dragging = false
      press.direction = null
      if (book.hasPointerCapture(event.pointerId)) {
        book.releasePointerCapture(event.pointerId)
      }
      setCursor('')
      const current = layoutRef.current
      if (!current) return

      if (dragging) {
        if (!direction) return
        if (settingsRef.current.reducedMotion) {
          if (!cancelled) turnPage(direction, { sound: true, announce: true })
          return
        }
        const turn = turnRef.current
        if (!turn) return
        // The page keeps going the way the hand left it: a flick turns it
        // from anywhere, a slow release reads by how far it got.
        const toward = direction === 'next' ? -velocity : velocity
        const travelled = direction === 'next' ? turn.p : 1 - turn.p
        const done = curlShouldCommit(travelled * 100, toward)
        if (done) commit(turn, true, true)
        const finished = direction === 'next' ? done : !done
        const remaining = done ? 1 - travelled : travelled
        animate(
          { p: finished ? 1 : 0, dy: 0 },
          curlSettleMs(remaining, velocity),
          easeOutCubic,
          endTurn,
        )
        return
      }

      if (cancelled) return
      // A tap: barely moved, and not already spent by the reader chrome.
      if (
        Math.hypot(pos.x - press.startX, pos.y - press.startY) >= press.slop
      ) {
        return
      }
      if (tapConsumedByChrome()) return
      const bookWidth = current.size.width * (current.spread ? 2 : 1)
      // On a spread each page is its own half: the right page goes on, the
      // left goes back.
      const intent = curlClickIntent(
        pos.x,
        bookWidth,
        targetOf('prev') !== null,
        targetOf('next') !== null,
      )
      if (!intent) return
      turnPage(intent, {
        top: pos.y < current.size.height / 2,
        sound: true,
        announce: true,
      })
    }

    book.addEventListener('pointerdown', onPointerDown)
    book.addEventListener('pointermove', onHover)
    book.addEventListener('pointerleave', onLeave)
    window.addEventListener('pointermove', onPointerMove, { passive: false })
    window.addEventListener('pointerup', finish)
    window.addEventListener('pointercancel', finish)
    return () => {
      book.removeEventListener('pointerdown', onPointerDown)
      book.removeEventListener('pointermove', onHover)
      book.removeEventListener('pointerleave', onLeave)
      window.removeEventListener('pointermove', onPointerMove)
      window.removeEventListener('pointerup', finish)
      window.removeEventListener('pointercancel', finish)
    }
  }, [
    animate,
    beginTurn,
    commit,
    endTurn,
    landInFlight,
    paint,
    stopAnimation,
    targetOf,
    turnPage,
  ])

  useEffect(() => () => stopAnimation(), [stopAnimation])

  // ---- render ------------------------------------------------------------

  const mounted = curlMountWindow(shown, pageIndex, pageCount, spread)
  const width = layout?.size.width ?? 280
  const height = layout?.size.height ?? Math.round(280 * pageRatio)
  const bookWidth = spread ? width * 2 : width
  const base = spread ? curlSpreadStart(shown) : shown
  const canGoPrev = curlStepTarget(base, -1, pageCount, spread) !== null
  const canGoNext = curlStepTarget(base, 1, pageCount, spread) !== null
  // A leaf's slot: in a spread, even pages sit left of the spine and odd
  // pages right; a single page is bound on its left.
  const sideOf = (index: number): CurlLeafSide =>
    spread && index % 2 === 0 ? 'left' : 'right'
  // The right-hand slot, where the turning leaf and its fold live.
  const rightSlot = spread ? width : 0
  const isInView = (index: number) =>
    spread ? index === base || index === base + 1 : index === shown

  return (
    <div
      ref={stageRef}
      className="relative flex h-full w-full min-w-0 touch-pan-y items-center justify-center p-3 select-none sm:p-4"
    >
      <Button
        type="button"
        variant="ghost"
        size="icon"
        aria-label="Previous page"
        // A pointer affordance: keyboard readers have arrow keys and the
        // pager, so these stay out of the tab order.
        tabIndex={-1}
        data-book-preview-stage-arrow
        disabled={!canGoPrev}
        className="absolute top-1/2 left-1 z-10 hidden min-h-11 min-w-11 -translate-y-1/2 [@media(hover:hover)_and_(pointer:fine)]:inline-flex"
        data-book-preview-press
        onClick={() => turnPage('prev', { sound: true, announce: true })}
      >
        <IconChevronLeft />
      </Button>
      <div
        data-book-preview-curl
        data-spread={spread || undefined}
        className="relative max-h-full max-w-full min-w-0"
        style={{ opacity: layout ? 1 : 0 }}
      >
        {pageCount > 1 ? (
          <>
            {/* The book block: thin stacked page edges flanking the book,
                thickest where the most leaves sit. Purely decorative. */}
            <div
              aria-hidden
              data-book-preview-curl-edge="prev"
              style={{ width: curlEdgeWidth(base) }}
            />
            <div
              aria-hidden
              data-book-preview-curl-edge="next"
              style={{
                width: curlEdgeWidth(pageCount - 1 - base - (spread ? 1 : 0)),
              }}
            />
          </>
        ) : null}
        <div
          ref={bookRef}
          data-book-preview-curl-book
          data-bp-tap-surface
          className="relative touch-pan-y overflow-hidden"
          style={{ width: bookWidth, height }}
        >
          {spread ? (
            // The inside of the back cover: plain paper under the last
            // leaf, so a lone final page never sits beside a hole.
            <div
              aria-hidden
              data-book-preview-curl-endpaper
              className="pointer-events-none absolute top-0 z-0"
              style={{ left: width, width, height, backgroundColor: leafBack }}
            />
          ) : null}
          {mounted.map((index) => (
            <div
              key={`front-${index}`}
              ref={(node) => {
                if (node) frontsRef.current.set(index, node)
                else frontsRef.current.delete(index)
              }}
              data-book-preview-curl-leaf={index}
              inert={!isInView(index)}
              aria-hidden={!isInView(index) || undefined}
              className="absolute top-0 overflow-hidden"
              style={{
                visibility: 'hidden',
                left: sideOf(index) === 'left' || !spread ? 0 : width,
                width,
                height,
              }}
            >
              {renderPage(index, sideOf(index))}
            </div>
          ))}
          {/* The fold lives in the right-hand page's own coordinates. */}
          <div
            aria-hidden
            className="pointer-events-none absolute top-0 z-[3]"
            style={{ left: rightSlot, width, height }}
          >
            <div
              ref={shadowRef}
              data-book-preview-curl-shadow
              className="absolute top-0 left-0 origin-top-left"
              style={{ opacity: 0 }}
            />
          </div>
          {/* A filter on the clipped back itself would be clipped away with
              it; on this wrapper it traces the lifted flap's edge, so white
              paper still reads against white paper. */}
          <div
            data-book-preview-curl-backs
            className="pointer-events-none absolute inset-0 z-[4]"
          >
            {mounted.map((index) =>
              // Single pages show their own face through the paper; a
              // spread's leaf carries the next left page on its back.
              spread && index % 2 === 1 ? null : (
                <div
                  key={`back-${index}`}
                  ref={(node) => {
                    if (node) backsRef.current.set(index, node)
                    else backsRef.current.delete(index)
                  }}
                  aria-hidden
                  inert
                  data-book-preview-curl-back
                  className="absolute top-0 origin-top-left overflow-hidden"
                  style={{
                    visibility: 'hidden',
                    left: rightSlot,
                    width,
                    height,
                    backgroundColor: leafBack,
                  }}
                >
                  {spread ? (
                    // Drawn mirrored, so the fold's mirror lands it reading
                    // the right way round on the left of the spine.
                    <div className="absolute inset-0 -scale-x-100">
                      {renderPage(index, 'left')}
                    </div>
                  ) : (
                    <div className="absolute inset-0 opacity-[0.07]">
                      {renderPage(index, 'right')}
                    </div>
                  )}
                  <div
                    data-book-preview-curl-gloss
                    className="absolute top-0 left-0 origin-top-left"
                  />
                </div>
              ),
            )}
          </div>
          {spread ? (
            <div
              aria-hidden
              data-book-preview-curl-spine
              className="pointer-events-none absolute top-0 z-[2]"
              style={{ left: width - 12, width: 24, height }}
            />
          ) : null}
        </div>
      </div>
      <Button
        type="button"
        variant="ghost"
        size="icon"
        aria-label="Next page"
        // A pointer affordance: keyboard readers have arrow keys and the
        // pager, so these stay out of the tab order.
        tabIndex={-1}
        data-book-preview-stage-arrow
        disabled={!canGoNext}
        className="absolute top-1/2 right-1 z-10 hidden min-h-11 min-w-11 -translate-y-1/2 [@media(hover:hover)_and_(pointer:fine)]:inline-flex"
        data-book-preview-press
        onClick={() => turnPage('next', { sound: true, announce: true })}
      >
        <IconChevronRight />
      </Button>
    </div>
  )
}

/** Lays a band along the fold: it starts on the fold line and reaches
    `reach` px toward the flap, long enough to span the page either way. */
function placeAlongFold(
  el: HTMLElement,
  origin: { x: number; y: number },
  angle: number,
  reach: number,
  size: CurlPageSize,
) {
  const span = Math.hypot(size.width, size.height) * 2
  el.style.width = `${Math.max(reach, 1)}px`
  el.style.height = `${span}px`
  el.style.transform = `translate(${origin.x}px, ${origin.y}px) rotate(${angle}deg) translateY(${-span / 2}px)`
}

'use client'

import type { ReactNode } from 'react'
import { BookPreviewPageView } from '../book-preview-page'
import type { PdfSheet } from '../hooks/use-pdf-sheets'
import type { BookPreviewEngineProps, BookPreviewPage } from '../types'
import { CurlPdfSheet } from './curl-pdf-sheet'

export function FlipSheet({ children }: { children: ReactNode }) {
  return (
    <div className="bg-background h-full w-full overflow-hidden">
      <div className="[pointer-events:none] h-full w-full [&_a]:pointer-events-auto [&_button]:pointer-events-auto">
        {children}
      </div>
    </div>
  )
}

/** One leaf of a curl book, from whichever source the book has. */
export function renderCurlLeaf(
  source: {
    usePdf: boolean
    sheets: PdfSheet[] | null
    pages: BookPreviewPage[]
    appearance: BookPreviewEngineProps['appearance']
  },
  index: number,
  side: 'left' | 'right' = 'right',
): ReactNode {
  if (source.usePdf) {
    const sheet = source.sheets?.[index]
    return sheet ? (
      <FlipSheet>
        <CurlPdfSheet src={sheet.src} />
      </FlipSheet>
    ) : null
  }
  const page = source.pages[index]
  return page ? (
    <FlipSheet>
      <BookPreviewPageView
        page={page}
        appearance={source.appearance}
        // Gutter shading sits on the spine side: a single-leaf book is bound
        // on the left (every leaf a right-hand page); a spread says which.
        isLeftPage={side === 'left'}
      />
    </FlipSheet>
  ) : null
}

/** Leaf count and a leaf renderer for a CurlStage. */
export function curlLeaves(source: Parameters<typeof renderCurlLeaf>[0]) {
  return {
    pageCount: source.usePdf
      ? (source.sheets?.length ?? 0)
      : source.pages.length,
    renderPage: (index: number, side: 'left' | 'right') =>
      renderCurlLeaf(source, index, side),
    // Rasterized pages are white paper whatever the theme.
    leafBack: source.usePdf ? '#fff' : undefined,
  }
}

'use client'

import { useEffect, useRef } from 'react'

/**
 * One rasterized PDF page inside the flip book.
 *
 * The leaf is white paper from the first frame — a pending raster shows a
 * faint paper-toned shimmer, never the theme's dark background, so a page
 * arriving mid-turn cannot flash dark → white. The <img> keeps its element
 * across src changes, so the browser holds the old bitmap until the new one
 * has decoded.
 */
export function CurlPdfSheet({ src }: { src: string }) {
  const imgRef = useRef<HTMLImageElement | null>(null)
  // Leaves around the reading position are mounted hidden; decode their
  // bitmaps now, so the frame a turn reveals one is never a blank frame.
  useEffect(() => {
    if (!src) return
    imgRef.current?.decode?.().catch(() => {})
  }, [src])
  return (
    <div className="relative h-full w-full bg-white">
      <div
        data-book-preview-sheet-skeleton
        className="absolute inset-0 animate-pulse bg-neutral-100"
        aria-hidden
      />
      {/* Object URLs are generated locally and cannot be optimized by next/image. */}
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        ref={imgRef}
        data-book-preview-sheet-img
        src={src || undefined}
        alt=""
        draggable={false}
        className="relative h-full w-full object-contain"
      />
    </div>
  )
}

'use client'

import { useEffect } from 'react'
import { DEFAULT_CAPABILITIES } from '../capabilities'
import { usePdfSheets } from '../hooks/use-pdf-sheets'
import { useStableHandler } from '../hooks/use-stable-handler'
import type { BookPreviewEngineProps } from '../types'
import { CURL_PAGE_RATIO, CURL_RASTER_WIDTH } from './curl-geometry'
import { CurlStage } from './curl-stage'
import { PdfPasswordGate } from './pdf-password-gate'
import { PdfPreparingBadge } from './pdf-preparing-badge'
import { resolvePdfOutline } from '../pdf-runtime'
import { curlLeaves } from './flip-sheet'

export default function CurlEngine({
  source,
  pageIndex,
  appearance,
  soundEnabled,
  reducedMotion,
  onPageChange,
  onReady,
  onError,
}: BookPreviewEngineProps) {
  const pages = source.pages
  const pdfUrl = source.pdfUrl
  const usePdf = Boolean(pdfUrl) && pages.length === 0
  const reportReady = useStableHandler(onReady)
  const reportError = useStableHandler(onError)

  const {
    sheets,
    ratio,
    prepared,
    preparing,
    doc,
    passwordRequest,
    submitPassword,
    cancelPassword,
  } = usePdfSheets({
    pdfUrl,
    enabled: usePdf,
    pageIndex,
    rasterWidth: CURL_RASTER_WIDTH,
    sizing: 'uniform',
    // The book mounts only the leaves around the reading position, so
    // rasters stay bounded however long the document is.
    // A spread turn reveals up to three pages past the left one; one more
    // keeps the spread after that already painted.
    windowRadius: 4,
    onError: reportError,
    errorMessage: 'This PDF could not be opened for curl.',
  })

  useEffect(() => {
    if (usePdf) {
      if (!sheets) return
      reportReady({
        totalPages: sheets.length,
        capabilities: {
          ...DEFAULT_CAPABILITIES,
          curl: true,
          spreads: false,
          appearance: false,
          download: Boolean(source.downloadUrl || source.pdfUrl),
        },
      })
      return
    }
    if (pages.length === 0) {
      reportError({
        kind: 'empty',
        message: 'The curl reader needs page data or a PDF.',
      })
      return
    }
    reportReady({
      totalPages: pages.length,
      capabilities: {
        ...DEFAULT_CAPABILITIES,
        curl: true,
        spreads: false,
        download: Boolean(source.downloadUrl),
      },
    })
  }, [
    pages.length,
    reportError,
    reportReady,
    sheets,
    source.downloadUrl,
    source.pdfUrl,
    usePdf,
  ])

  // A password prompt still counts as "open": reporting a zero-page ready
  // unblocks the viewport so the gate is visible, and pagination stays off
  // until the document's real page count arrives.
  useEffect(() => {
    if (!passwordRequest) return
    reportReady({
      totalPages: 0,
      capabilities: {
        ...DEFAULT_CAPABILITIES,
        pagination: false,
        appearance: false,
        sound: false,
        download: false,
      },
    })
  }, [passwordRequest, reportReady])

  // The author's outline becomes the reader's table of contents — a second
  // ready call so a slow bookmark walk never delays the first page.
  useEffect(() => {
    if (!doc) return
    let cancelled = false
    void resolvePdfOutline(doc).then((contents) => {
      if (cancelled || contents.length === 0) return
      reportReady({
        totalPages: doc.numPages,
        capabilities: {
          ...DEFAULT_CAPABILITIES,
          curl: true,
          spreads: false,
          appearance: false,
          download: Boolean(source.downloadUrl || source.pdfUrl),
        },
        contents,
      })
    })
    return () => {
      cancelled = true
    }
  }, [doc, reportReady, source.downloadUrl, source.pdfUrl])

  if (usePdf && !sheets) {
    if (passwordRequest) {
      return (
        <div className="flex h-full items-center justify-center p-4">
          <PdfPasswordGate
            fileName={source.pdfFileName}
            incorrect={passwordRequest.incorrect}
            onSubmit={submitPassword}
            onCancel={cancelPassword}
          />
        </div>
      )
    }
    return (
      <div className="text-muted-foreground flex h-full items-center justify-center text-sm">
        Opening PDF…
      </div>
    )
  }

  return (
    <div className="relative h-full w-full">
      <CurlStage
        pageIndex={pageIndex}
        {...curlLeaves({ usePdf, sheets, pages, appearance })}
        pageRatio={usePdf ? (ratio ?? CURL_PAGE_RATIO) : CURL_PAGE_RATIO}
        reducedMotion={reducedMotion}
        soundEnabled={soundEnabled}
        onPageChange={onPageChange}
      />
      {preparing && sheets ? (
        <PdfPreparingBadge prepared={prepared} total={sheets.length} />
      ) : null}
    </div>
  )
}

/**
 * Page-curl geometry. A turning leaf is modelled as a flat sheet folded along
 * one line: the part past the fold lifts and lands mirrored on top of the
 * rest. Everything here is in page coordinates — the spine is the left edge
 * (x = 0), the leaf is `width` × `height` — and pure, so bun tests it
 * without a browser.
 *
 * A turn is described by its grabbed corner and a progress `p` (0 = flat on
 * the page, 1 = fully turned over the spine). The drag point — where the
 * grabbed corner is now — follows from those two, and the fold line is the
 * perpendicular bisector between the corner and the drag point.
 */

export type Vec = { x: number; y: number }

/** How far a corner rises through a turn, as a share of the page height. A
    straight horizontal pull gives a flat vertical fold; the lift is what
    makes it read as a curl. */
export const CURL_ARC_LIFT = 0.12

/** Hover peek: the corner lifts this much (progress) under a resting mouse. */
export const CURL_PEEK_PROGRESS = 0.035

export type CurlFold = {
  /** Still-flat part of the leaf's front, as a polygon. */
  front: Vec[]
  /** Part of the leaf that has lifted, in its original (flat) position. */
  flap: Vec[]
  /** CSS `matrix()` values mirroring page coordinates across the fold —
      applied to the leaf's back, clipped to `flap`, it lands the flap. */
  matrix: [number, number, number, number, number, number]
  /** A point on the fold line and the unit normal pointing to the flap. */
  origin: Vec
  normal: Vec
  /** Angle of `normal` in degrees, for rotating shadows along the fold. */
  angle: number
  /** Distance from the fold to the far edge of the flap. */
  depth: number
}

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value))
}

/** The corner a press grabs: the top one in the top half, else the bottom. */
export function curlCornerFor(y: number, width: number, height: number): Vec {
  return { x: width, y: y < height / 2 ? 0 : height }
}

/**
 * Where the grabbed corner sits at progress `p`. It travels from its own
 * position to its mirror image across the spine, rising on an arc so the
 * fold runs diagonally mid-turn. `dy` is the reader's own vertical pull.
 */
export function curlDragPoint(
  corner: Vec,
  p: number,
  dy: number,
  height: number,
): Vec {
  const t = clamp(p, 0, 1)
  const rise = CURL_ARC_LIFT * height * Math.sin(Math.PI * t)
  // A bottom corner rises; a top corner dips.
  const toward = corner.y > height / 2 ? -1 : 1
  return {
    x: corner.x - 2 * corner.x * t,
    y: corner.y + dy + toward * rise,
  }
}

function projectToDisc(point: Vec, center: Vec, radius: number): Vec {
  const dx = point.x - center.x
  const dy = point.y - center.y
  const distance = Math.hypot(dx, dy)
  if (distance <= radius || distance === 0) return point
  const scale = radius / distance
  return { x: center.x + dx * scale, y: center.y + dy * scale }
}

/**
 * Keeps a drag physically possible: paper cannot stretch or tear from the
 * spine, so both spine corners stay on the flat side of the fold — the drag
 * point stays inside a disc around each, with the grabbed corner's distance
 * as radius. Alternating projections settle into the lens they share.
 */
export function constrainCurlDrag(corner: Vec, drag: Vec, height: number): Vec {
  const top = { x: 0, y: 0 }
  const bottom = { x: 0, y: height }
  const rTop = Math.hypot(corner.x - top.x, corner.y - top.y)
  const rBottom = Math.hypot(corner.x - bottom.x, corner.y - bottom.y)
  // Pulling past the corner's own edge folds nothing.
  let point = { x: Math.min(drag.x, corner.x), y: drag.y }
  for (let pass = 0; pass < 4; pass += 1) {
    point = projectToDisc(point, top, rTop)
    point = projectToDisc(point, bottom, rBottom)
  }
  return point
}

/** Sutherland–Hodgman against one half-plane: keeps the points where
    `(p - origin) · normal` has the requested sign. */
export function clipPolygon(
  polygon: readonly Vec[],
  origin: Vec,
  normal: Vec,
  keep: 'positive' | 'negative',
): Vec[] {
  const sign = keep === 'positive' ? 1 : -1
  const side = (p: Vec) =>
    sign * ((p.x - origin.x) * normal.x + (p.y - origin.y) * normal.y)
  const out: Vec[] = []
  for (let index = 0; index < polygon.length; index += 1) {
    const current = polygon[index]
    const next = polygon[(index + 1) % polygon.length]
    const a = side(current)
    const b = side(next)
    if (a >= 0) out.push(current)
    if (a >= 0 !== b >= 0) {
      const t = a / (a - b)
      out.push({
        x: current.x + (next.x - current.x) * t,
        y: current.y + (next.y - current.y) * t,
      })
    }
  }
  return out
}

/**
 * The fold for a corner dragged to `drag` (already constrained). Null when
 * nothing is lifted — the leaf lies flat.
 */
export function curlFold(
  corner: Vec,
  drag: Vec,
  width: number,
  height: number,
): CurlFold | null {
  const dx = corner.x - drag.x
  const dy = corner.y - drag.y
  const length = Math.hypot(dx, dy)
  if (length < 0.5) return null
  const normal = { x: dx / length, y: dy / length }
  const origin = { x: (corner.x + drag.x) / 2, y: (corner.y + drag.y) / 2 }
  const page = [
    { x: 0, y: 0 },
    { x: width, y: 0 },
    { x: width, y: height },
    { x: 0, y: height },
  ]
  const front = clipPolygon(page, origin, normal, 'negative')
  const flap = clipPolygon(page, origin, normal, 'positive')
  if (flap.length < 3) return null
  // Reflection across the fold: x' = x - 2((x - o)·n)n.
  const k = 2 * (origin.x * normal.x + origin.y * normal.y)
  const matrix: CurlFold['matrix'] = [
    1 - 2 * normal.x * normal.x,
    -2 * normal.x * normal.y,
    -2 * normal.x * normal.y,
    1 - 2 * normal.y * normal.y,
    k * normal.x,
    k * normal.y,
  ]
  let depth = 0
  for (const point of flap) {
    depth = Math.max(
      depth,
      (point.x - origin.x) * normal.x + (point.y - origin.y) * normal.y,
    )
  }
  return {
    front,
    flap,
    matrix,
    origin,
    normal,
    angle: (Math.atan2(normal.y, normal.x) * 180) / Math.PI,
    depth,
  }
}

/** Mirror a point across the fold the way `matrix` does — for tests. */
export function applyCurlMatrix(matrix: CurlFold['matrix'], point: Vec): Vec {
  const [a, b, c, d, e, f] = matrix
  return { x: a * point.x + c * point.y + e, y: b * point.x + d * point.y + f }
}

/** CSS `polygon()` for a clip path, rounded to keep style strings short. */
export function curlPolygonCss(points: readonly Vec[]): string {
  if (points.length < 3) return 'polygon(0 0, 0 0, 0 0)'
  return `polygon(${points
    .map((p) => `${Math.round(p.x * 10) / 10}px ${Math.round(p.y * 10) / 10}px`)
    .join(', ')})`
}

/**
 * Progress of a forward drag: the finger holds the grabbed point of the
 * paper, so the corner moves exactly as far as the finger has.
 */
export function curlForwardProgress(
  startX: number,
  x: number,
  width: number,
): number {
  return clamp((startX - x) / (2 * Math.max(width, 1)), 0, 1)
}

/**
 * Progress of a backward drag on a single page. The previous leaf lies
 * turned over, off the page to the left, so there is no paper under the
 * finger to hold — instead the fold edge follows it: from where the press
 * began to the right edge, the leaf unfolds across the whole page.
 */
export function curlBackwardProgress(
  startX: number,
  x: number,
  width: number,
): number {
  const room = Math.max(width - startX, 1)
  const unfolded = clamp((x - startX) / room, 0, 1)
  return 1 - unfolded
}

/**
 * Progress of a backward drag across a spread. The turned leaf lies on the
 * left page, so the finger holds its paper just as it does going forward:
 * the corner travels exactly as far as the finger, across both pages.
 */
export function curlSpreadBackwardProgress(
  startX: number,
  x: number,
  width: number,
): number {
  return clamp(1 - (x - startX) / (2 * Math.max(width, 1)), 0, 1)
}

/** Ease-out: already moving, settling. */
export function easeOutCubic(t: number): number {
  const u = 1 - clamp(t, 0, 1)
  return 1 - u * u * u
}

/** Ease-in-out: a turn from rest gathers, travels, lands. */
export function easeInOutCubic(t: number): number {
  const u = clamp(t, 0, 1)
  return u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) / 2
}

/** Release duration (ms): shorter the less there is left to travel, and
    shorter still after a fast flick — the page keeps the finger's pace. */
export function curlSettleMs(remaining: number, speed: number): number {
  const base = 150 + 330 * clamp(remaining, 0, 1)
  const quick = clamp(Math.abs(speed) / 1.5, 0, 1)
  return Math.round(base * (1 - 0.4 * quick))
}

/** Pages kept mounted around the one in view: the leaf behind, the leaf
    under, one more ahead so its raster is ready when the turn lands. */
export function curlWindow(
  index: number,
  pageCount: number,
  extra: readonly number[] = [],
): number[] {
  const set = new Set<number>()
  for (const center of [index, ...extra]) {
    for (let offset = -1; offset <= 2; offset += 1) {
      const page = center + offset
      if (page >= 0 && page < pageCount) set.add(page)
    }
  }
  return Array.from(set).sort((a, b) => a - b)
}
